    <td><input size="4" id="bd-${r.batch_id}" value="${r.duplicate_risk_count??''}" ${r.locked?'disabled':''}></td>
    <td><input size="8" id="bp-${r.batch_id}" value="${r.penalty_cny??''}" ${r.locked?'disabled':''}></td>
