import json, csv, collections
from datetime import datetime, timezone, timedelta
UTC8=timezone(timedelta(hours=8))
def parse(ts): return datetime.fromisoformat(ts.replace('Z','+00:00')).astimezone(UTC8)
rows=[json.loads(l) for l in open('data/gateway_requests.jsonl')]
for r in rows: r['dt']=parse(r['timestamp'])
prod=[r for r in rows if not r['merchant_id'].startswith('TEST_')]
by_tx=collections.defaultdict(list)
for r in prod: by_tx[r['tx_id']].append(r)
final={tx:sorted(att,key=lambda r:(r['dt'],r.get('attempt',0)))[-1] for tx,att in by_tx.items()}
b=list(csv.DictReader(open('data/settlement_batches_raw.csv')))
# VIP_003 maintenance window check
print('=== MCH_VIP_003 txs with final ts in 00:00:00-00:59:59 UTC+8 (any day) ===')
for r in b:
    if r['merchant_id']=='MCH_VIP_003':
        f=final[r['tx_id']]
        if f['dt'].hour==0:
            att=by_tx[r['tx_id']]
            dup=any(a['status']=='SETTLED' for a in sorted(att,key=lambda x:(x['dt'],x.get('attempt',0)))[:-1])
            print(r['tx_id'], 'final:', f['dt'].isoformat(), f['status'], f['latency_ms'],'ms', '| DUP_RISK' if dup else '', '| cycle:', r['cycle_time'])
print()
print('=== NEXTDAY txs merchant/status ===')
for tx,f in final.items():
    if 'NEXTDAY' in tx: print(tx, f['merchant_id'], f['status'], f['latency_ms'], f['dt'].isoformat())
print()
# per-batch final status/latency distribution
for bid in sorted({r['batch_id'] for r in b}):
    brs=[r for r in b if r['batch_id']==bid]
    st=collections.Counter(final[r['tx_id']]['status'] for r in brs)
    print(bid, brs[0]['merchant_id'], brs[0]['tier'], brs[0]['currency'], 'n=',len(brs), dict(st))
EOF

