# Independent cross-check with a different implementation path
import json, csv
from datetime import datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP
U8=timezone(timedelta(hours=8))
def ts(s):
    if s.endswith('Z'): return datetime.strptime(s,'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=timezone.utc).astimezone(U8)
    return datetime.fromisoformat(s)
log=[json.loads(l) for l in open('/workspace/data/gateway_requests.jsonl')]
log=[r for r in log if not r['merchant_id'].startswith('TEST_')]
# group & pick max by (parsed time, attempt)
best={}
for r in log:
    t=ts(r['timestamp'])
    if r['tx_id'] not in best or (t,r['attempt'])>(best[r['tx_id']][0],best[r['tx_id']][1]['attempt']):
        best[r['tx_id']]=(t,r)
dup=set()
for r in log:
    t=ts(r['timestamp'])
    b=best[r['tx_id']]
    if r['status']=='SETTLED' and (t,r['attempt'])<(b[0],b[1]['attempt']): dup.add(r['tx_id'])
fx={'USD':Decimal('7.15'),'HKD':Decimal('0.92'),'CNY':Decimal('1')}
th={'VIP_T1':600,'STD':1500}; rate={'VIP_T1':Decimal('0.025'),'STD':Decimal('0.005')}
out={}
for r in csv.DictReader(open('/workspace/data/settlement_batches_raw.csv')):
    t,f=best[r['tx_id']]
    if t.strftime('%Y-%m-%d')!='2026-11-24': continue
    bid=r['batch_id']; o=out.setdefault(bid,{'settled':Decimal(0),'pen':Decimal(0),'b':0,'d':0,'ex':0,'status_mix':{}})
    cny=(Decimal(r['amount_orig'])*fx[r['currency']]).quantize(Decimal('0.01'),ROUND_HALF_UP)
    o['settled']+=cny
    o['status_mix'][f['status']]=o['status_mix'].get(f['status'],0)+1
    isdup=r['tx_id'] in dup
    ex=r['merchant_id']=='MCH_VIP_003' and t.hour==0 and not isdup
    br=(f['status'] in ('TIMEOUT','504','FAILED') or f['latency_ms']>th[r['tier']]) and not ex
    o['d']+=isdup; o['ex']+=ex
    if br: o['b']+=1; o['pen']+=cny*rate[r['tier']]
    if br and f['status']=='SETTLED': o.setdefault('settled_breach_lat',[]).append((r['tx_id'],f['latency_ms']))
tot=Decimal(0)
for bid,o in sorted(out.items()):
    pen=o['pen'].quantize(Decimal('0.01'),ROUND_HALF_UP)
    if bid!='BATCH-20261124-03': pen=min(Decimal('5000.00'),pen)
    tot+=pen
    print(bid,'settled',o['settled'],'breach',o['b'],'dup',o['d'],'exempt',o['ex'],'penalty',pen,'mix',o['status_mix'])
print('TOTAL',tot)
# compare with primary script
prim=json.load(open('/tmp/audit_result.json'))
for s in prim['summary']:
    o=out[s['batch_id']]
    pen=o['pen'].quantize(Decimal('0.01'),ROUND_HALF_UP)
    if s['batch_id']!='BATCH-20261124-03': pen=min(Decimal('5000.00'),pen)
    assert f"{o['settled']:.2f}"==s['settled_amount_cny'], (s['batch_id'],'settled')
    assert o['b']==s['breached_tx_count'] and o['d']==s['duplicate_risk_count']
    assert f"{pen:.2f}"==s['penalty_cny'], (s['batch_id'],'penalty')
assert f"{tot:.2f}"==prim['total_penalty_cny']
print('CROSS-CHECK: ALL MATCH')
# show settled-but-slow breaches per batch for the report
for bid,o in sorted(out.items()):
    print(bid,'SETTLED>threshold:',sorted(o.get('settled_breach_lat',[])))
EOF

